DROP VIEW IF EXISTS replset.vw_month_bank_expenses_to_allocate CASCADE;  CREATE OR REPLACE VIEW replset.vw_month_bank_expenses_to_allocate AS  SELECT date_trunc('month'::text, date_period) AS repmonth,     organization_code AS orgs_code,     shop_code,     sum(amount) AS amount,     sum(amountvat) AS amountvat,     sum(amountwithvat) AS amountwithvat    FROM vw_bank_expenses_to_allocate   GROUP BY (date_trunc('month'::text, date_period)), organization_code, shop_code;
